-- Viva question bank, managed from the admin panel (Viva Questions tab) and read by the FastAPI backend.
-- Answers are the marking key, so only admins can read this table from the browser; the backend uses the service role key.
create table if not exists public.viva_questions (
  id bigint generated by default as identity primary key,
  chapter_no integer not null,
  chapter text not null,
  topic text not null,
  concept text,
  question text not null,
  answer text not null,
  source text not null default '',
  diagram_required boolean not null default false,
  active boolean not null default true,
  created_at timestamptz not null default now()
);

create index if not exists viva_questions_chapter_topic_idx on public.viva_questions (chapter_no, topic) where active;

alter table public.viva_questions enable row level security;

create policy "Admins read viva questions" on public.viva_questions
  for select to authenticated using (public.has_role(auth.uid(), 'admin'));
create policy "Admins insert viva questions" on public.viva_questions
  for insert to authenticated with check (public.has_role(auth.uid(), 'admin'));
create policy "Admins update viva questions" on public.viva_questions
  for update to authenticated using (public.has_role(auth.uid(), 'admin')) with check (public.has_role(auth.uid(), 'admin'));
create policy "Admins delete viva questions" on public.viva_questions
  for delete to authenticated using (public.has_role(auth.uid(), 'admin'));

-- Existing bank (the JSON file the backend used to read), keeping its ids.
Arrhenius Acid: A substance that increases the concentration of hydrogen ions (H) or protons in aqueous solution.
